  \draw[ink, line width=0.4pt] (1.05,-0.05) -- (1.05,-0.616);
  \draw[ink, <->, line width=0.6pt] (0,-0.536) -- (1.05,-0.536);
  \node[below, font=\scriptsize] at (0.525,-0.536) {$5$ cm};
  \node[right, font=\scriptsize] at (0.565,1.05) {$13$ cm};
  \node[above, font=\scriptsize] at (0,2) {$C$};
